// Localized anatomical names, generated by `npm run translate`. Anything missing falls back to the English name.
import ja from '../data/partnames.ja.json';
import ne from '../data/partnames.ne.json';
import type { Lang } from './i18n';
import { parsePart } from './partName';

const MAPS: Record<Lang, Record<string, string>> = {
  en: {},
  ne: ne as Record<string, string>,
  ja: ja as Record<string, string>,
};

/** Localized name for a raw model name (e.g. "Adductor_brevis.l"), without the side. */
export function localName(raw: string, lang: Lang): string {
  const p = parsePart(raw);
  return MAPS[lang][p.base] ?? p.display;
}
